// Normalize Salesforce's vocabulary into Meridian's, and mint the two
// identifiers the rest of the transaction depends on.
//
// The idempotency key is derived from the opportunity ID plus the record's
// LastModifiedDate — NOT from a timestamp or a random value. Salesforce
// delivers at-least-once, so a retry of the same change must produce the
// same key or duplicate protection cannot work. Including LastModifiedDate
// means a genuinely new change to the same opportunity is a new event,
// which is the behaviour you want.
//
// The correlation ID is minted here because this is the true edge of the
// transaction. Everything downstream — Meridian, Jira, Slack — carries it,
// which is what makes the whole flow searchable from one string.

const body = $json.body;

const opportunityId = body.Id;
const lastModified = body.LastModifiedDate || 'unknown';
const idempotencyKey = `sf-opp-${opportunityId}-${lastModified}`;

const correlationId = `n8n-${$execution.id}-${opportunityId}`;

return {
  json: {
    correlation_id: correlationId,
    idempotency_key: idempotencyKey,
    account: {
      id: body.AccountId,
      name: body.AccountName || body.Account?.Name || 'Unknown Account',
      website: body.AccountWebsite || body.Account?.Website || null
    },
    opportunity: {
      id: opportunityId,
      name: body.Name,
      is_won: body.IsWon === true,
      is_closed: body.IsClosed === true,
      amount: body.Amount ?? null
    }
  }
};

// HMAC-SHA256 over the exact bytes we are about to send.
//
// Signing the serialized string and then sending that same string matters:
// signing an object and letting the HTTP node re-serialize it would change
// key order or whitespace and produce a signature the backend cannot
// reproduce. That failure is intermittent and extremely unpleasant to
// diagnose, so the body is frozen here and sent verbatim.

const crypto = require('crypto');

const secret = $env.MERIDIAN_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('MERIDIAN_WEBHOOK_SECRET is not set — refusing to send an unsigned event');
}

const bodyString = JSON.stringify($json);
const signature = crypto.createHmac('sha256', secret).update(bodyString).digest('hex');

return {
  json: {
    body_string: bodyString,
    signature,
    idempotency_key: $json.idempotency_key,
    correlation_id: $json.correlation_id
  }
};

// 200 = first delivery, 208 = duplicate we already had. Both are
// success; the distinction is worth surfacing in Slack so an operator can
// see that a retry was recognised rather than acted on twice.
const status = $json.statusCode;
const outcome = status === 208 ? 'duplicate (already processed)' : 'accepted';
return { json: { outcome, status, correlation_id: $json.body?.correlation_id } };

// Deliberately does NOT echo the response body into the alert. A provider
// error body can carry tokens or customer data, and a Slack channel is a
// long-lived, widely-readable store. Status code plus correlation ID is
// enough to find the full, redacted record in Meridian's support console.
return {
  json: {
    status: $json.statusCode,
    correlation_id: $json.correlation_id ?? 'unknown',
    message: `Meridian rejected an onboarding event (HTTP ${$json.statusCode}). Investigate by correlation ID.`
  }
};
